 Kembalikan janji baru ((menyelesaikan, menolak) => {
 setTimeout (() => {
 biarkan hasil = x + y;
 jika (hasil> = 0) {
 menyelesaikan (hasil);
 } else {
 menolak ('hasil adalah negatif');
 }
 }, 1000);
 });
}

english:
Rewrite the following code to use the async/await syntax:

function add2Numbers(x, y) {
 return new Promise((resolve, reject) => {
 setTimeout(() => {
 let result = x + y;
 if(result >= 0) {
 resolve(result);
 } else {
 reject('Result is negative');
 }
 }, 1000);
 });
}

